    .catch(err => console.error('SW registration failed:', err));
}
```

In `sw.js`, handle the lifecycle events:

```js
self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open('v1').then(cache => cache.addAll(['/', '/index.html', '/style.css']))
  );
});

self.addEventListener('fetch', (event) => {
  event.respondWith(
    caches.match(event.request).then(response => response || fetch(event.request))
  );
});
```

**Caveats**

- Requires HTTPS in production (browsers exempt `localhost` for dev).
- The `sw.js` file's location determines its default scope (e.g., a worker at `/app/sw.js` can only control pages under `/app/`).
- Browsers cache the service worker file itself aggressively — during development, hard-refresh or use the DevTools "Update on reload" option, or you'll keep loading a stale version.
- Feature support is broad (Chrome, Firefox, Edge, Safari) but check specifics (e.g., Background Sync) on caniuse.com if you rely on advanced APIs.
